import{I as r,o as c,c as m,j as e,a as i,J as s,w as t,b6 as a,cN as b,cO as f,cP as k,cQ as w,cR as z,cS as S,cT as v,cU as P,cV as A,cW as I,cX as E,cY as y,cZ as _,c_ as q,c$ as C,d0 as B,d1 as W,d2 as D,d3 as T,k as V}from"./chunks/framework.BUXTSoD9.js";import{r as G}from"./chunks/relatedArticles.DIHQAH-1.js";const x={style:{margin:"50px 0"}},F={style:{margin:"50px 0"}},M={style:{margin:"50px 0"}},N={style:{margin:"50px 0"}},H=JSON.parse('{"title":"Prototyp erstellen - Von der Geschäftsanalyse zur Multi-Page-Produktprototyp-Implementierung","description":"Den vollständigen Kreislauf von der Geschäftsanalyse zur Multi-Page-Produktprototyp-Implementierung erleben. Lernen Sie, wie man das Geschäft befragt, Anforderungen zerlegt, AI IDE für Single-Page- und Multi-Page-Anwendungen nutzt und den Prototyp optimiert und testet.","frontmatter":{"title":"Prototyp erstellen - Von der Geschäftsanalyse zur Multi-Page-Produktprototyp-Implementierung","description":"Den vollständigen Kreislauf von der Geschäftsanalyse zur Multi-Page-Produktprototyp-Implementierung erleben. Lernen Sie, wie man das Geschäft befragt, Anforderungen zerlegt, AI IDE für Single-Page- und Multi-Page-Anwendungen nutzt und den Prototyp optimiert und testet."},"headers":[],"relativePath":"de-de/stage-1/building-prototype/index.md","filePath":"de-de/stage-1/building-prototype/index.md"}'),K={name:"de-de/stage-1/building-prototype/index.md"},L=Object.assign(K,{setup(O){const d="Etwa <strong>8 Stunden</strong>",p=G["de-de/stage-1/building-prototype"]??[];return(j,n)=>{const g=r("ChapterIntroduction"),l=r("StepBar"),o=r("ClientOnly"),u=r("el-card"),h=r("RelatedArticlesSection");return c(),m("div",null,[n[5]||(n[5]=e("h1",{id:"anfanger-iii-prototyp-erstellen",tabindex:"-1"},[i("Anfänger III: Prototyp erstellen "),e("a",{class:"header-anchor",href:"#anfanger-iii-prototyp-erstellen","aria-label":"Permalink to “Anfänger III: Prototyp erstellen”"},"​")],-1)),n[6]||(n[6]=e("h2",{id:"kapitelubersicht",tabindex:"-1"},[i("Kapitelübersicht "),e("a",{class:"header-anchor",href:"#kapitelubersicht","aria-label":"Permalink to “Kapitelübersicht”"},"​")],-1)),s(g,{duration:d,tags:["Geschäftsanalyse","Prototyp-Design","AI-unterstützte Programmierung","Multi-Page-Anwendung"],coreOutput:"1 E-Commerce-Material-Workspace-Prototyp",expectedOutput:"Interaktiver Web-Prototyp"},{default:t(()=>[...n[0]||(n[0]=[e("p",null,[i("Im letzten Kapitel haben wir gelernt, wie man "),e("strong",null,"gute Ideen findet"),i(" — von Nutzerbedürfnissen ausgehend und Richtungen findet, für die jemand zu zahlen bereit ist. Aber eine Richtung zu finden ist nur der erste Schritt. "),e("strong",null,"Die wahre Herausforderung für Produktmanager ist: Wie verwandelt man vage Anforderungen in ein nutzbares Produkt?")],-1),e("p",null,[i("Dieses Kapitel löst ein "),e("strong",null,"reales Problem"),i(': Der Chef gibt Ihnen den Satz "Nutze AI, um die Effizienz beim Veröffentlichen von Produkten auf E-Commerce-Plattformen zu steigern" — wie machen Sie daraus einen '),e("strong",null,"nutzbaren Produktprototyp"),i("?")],-1),e("p",null,[i("Im Gegensatz zum Snake-Spiel oder Taschenrechner zuvor "),e("strong",null,"kann man bei echten Geschäften nicht einfach Funktionen erfinden"),i(":")],-1),e("ol",null,[e("li",null,[e("strong",null,"Schmerzpunkte klären"),i(': Mit dem Operations-Team sprechen, aus dem vagen "Effizienz steigern" die '),e("strong",null,"echten Schmerzpunkte"),i(" herausholen")]),e("li",null,[e("strong",null,"Prioritäten setzen"),i(": Aus vielen Problemen zunächst das "),e("strong",null,"schmerzhafteste"),i(" lösen, nicht alles auf einmal")]),e("li",null,[e("strong",null,"Schnell validieren"),i(": Mit AI IDE zunächst einen "),e("strong",null,"Single-Page-Prototyp"),i(" erstellen, wenn er funktioniert, zu Multi-Page erweitern")]),e("li",null,[e("strong",null,"Etwas Nutzbares erstellen"),i(": Am Ende einen "),e("strong",null,"demo-fähigen, bedienbaren E-Commerce-Material-Workspace"),i(" liefern")])],-1),e("p",null,[i("Wir lernen den "),e("strong",null,"Übergang vom Spielzeug zur Anwendung"),i(" und entwickeln "),e("strong",null,"Einfühlungsvermögen und das Nachdenken über echte Kundenbedürfnisse"),i(".")],-1)])]),_:1}),n[7]||(n[7]=e("div",{class:"info custom-block"},[e("p",{class:"custom-block-title"},"Hinweis"),e("p",null,"In diesem Artikel könnten einige Geschäftsbegriffe vorkommen. Wenn Sie diese nicht verstheen, können Sie AI um eine Erklärung bitten.")],-1)),e("div",x,[s(o,null,{default:t(()=>[s(l,{active:0,items:[{title:"Anforderungsanalyse",description:"Von vage zu konkret"},{title:"Single-Page-Validierung",description:"Kernfunktion implementieren"},{title:"Multi-Page-Erweiterung",description:"Anwendungsstruktur vervollständigen"},{title:"Optimierung",description:"Nutzererfahrung verbessern"}]})]),_:1})]),n[8]||(n[8]=a('<h2 id="_1-anforderungen-klaren-bevor-man-code-schreibt" tabindex="-1">1. Anforderungen klären, bevor man Code schreibt <a class="header-anchor" href="#_1-anforderungen-klaren-bevor-man-code-schreibt" aria-label="Permalink to “1. Anforderungen klären, bevor man Code schreibt”">​</a></h2><p>In den bisherigen Tutorials haben wir mit AI IDE mühelos Snake und verschiedene kleine Spiele generiert, aber das sind lediglich Spielzeugprojekte, die nicht im Berufs- oder Alltag eingesetzt werden können. Wenn wir AI-Fähigkeiten wirklich für alle nutzbar machen wollen, sollten wir Vibe Coding mit Lebens- und Arbeitsszenarien verbinden.</p><p>Im letzten Kapitel haben wir gelernt, wie man <strong>gute Ideen findet, für die jemand zu zahlen bereit ist</strong>. Aber eine Richtung zu finden ist nur der Anfang. Bei der echten Produktentwicklung werden Sie feststellen: <strong>Zwischen &quot;wissen, was zu tun ist&quot; und &quot;wissen, wie man es umsetzt&quot; liegt eine gewaltige Kluft.</strong></p><p>Diese Kluft ist die <strong>Konkretisierung von Anforderungen</strong>.</p><p>Ein Beispiel: In Kurs- oder persönlichen Projekten beginnen wir oft mit der einfachsten ausführbaren Funktion:</p><ul><li>&quot;Mach ein Kanban-Board, liste die Aufgaben auf.&quot;</li><li>&quot;Hilf mir, ein Zeichen-Tool zu erstellen.&quot;</li><li>&quot;Hilf mir, eine Umfrage-Software zu bauen.&quot;</li></ul><p>Das sind oft nur ein Tool oder ein Funktionsmodul – nicht einmal ein klares Geschäftsproblem. Noch wichtiger: <strong>Diese Ideen sind oft nur &quot;nützlich in Ihrer Meinung&quot;, nicht &quot;was Nutzer wirklich brauchen.&quot;</strong></p><p>In Unternehmens- oder Gründungsprojekten gehen Produktmanager und Ingenieure oft von einer größeren geschäftlichen Aufgabenstellung aus. Nehmen wir folgendes Szenario an:</p>',8)),s(u,{shadow:"hover",style:{"border-left":"5px solid #409EFF","background-color":"#ecf5ff",margin:"20px 0"}},{default:t(()=>[...n[1]||(n[1]=[e("div",{style:{"font-weight":"bold",color:"#303133","margin-bottom":"10px"}},"Geschäftsszenario:",-1),e("div",{style:{color:"#606266","line-height":"1.6"}},[e("p",null,"Sie sind der E-Commerce-Operations-Produktmanager eines Shops. Der Chef gibt Ihnen eine vage, aber druckvolle Aufgabenstellung:"),e("p",{style:{"font-style":"italic","margin-top":"10px"}},'"Alle nutzen AI für Bilder und Copywriting in WeChat-Öffentlichkeitskanälen, ganz einfach. Mach mal, dass wir beim Einstellen neuer Produkte auf Douyin E-Commerce effizienter werden."')],-1)])]),_:1}),n[9]||(n[9]=a(`<p>Jetzt denken Sie vielleicht: &quot;Chef, Sie träumen schon wieder!&quot; In der Praxis ist solch vages Diktat jedoch sehr häufig – sogar häufiger als Ihre wöchentliche Bubble-Tea-Bestellung. Um ein fähiger Angestellter (oder besser: CEO eines Startups) zu sein, müssen wir lernen, von Selbstnutzungs-Tools zu echten Produktprototypen zu wechseln.</p><p>Da wir AI IDE gelernt haben, fällt uns diese Anforderung eigentlich leicht – man muss AI nur einen Prompt geben, alles erledigt der Agent:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Bitte beziehe dich auf meine Anforderung xxxx,</span></span>
<span class="line"><span>hilf mir, einen E-Commerce-Material-Workspace zu entwerfen,</span></span>
<span class="line"><span>der Generierung und Verwaltung von Produktbeschreibungen, Bildern, Videos etc. umfasst.</span></span></code></pre></div><p>Wenn Sie begeistert diese Anforderung direkt in einen Prototyp umsetzen und dem Chef schicken – herzlichen Glückwunsch, Ihre Quartalsprämie ist gestrichen!</p><p><strong>Warum ist das so? Das ist genau der Kernschmerzpunkt, den wir lösen müssen:</strong></p><p>Bisher haben wir mit AI IDE nur Spielzeugprojekte wie Snake oder Taschenrechner gemacht – einfache Funktionen, man weiß, was man will, und man nutzt sie selbst. Aber <strong>echte Geschäftsszenarien sind völlig anders</strong>:</p><ul><li><strong>Sie sind nicht der Nutzer</strong>: Der Chef will &quot;Effizienz steigern&quot;, aber Sie wissen nicht, wie das Operations-Team täglich arbeitet und wo es hängt</li><li><strong>AI kennt das Geschäft nicht</strong>: Sie geben AI eine vage Anforderung, und es kann nur auf generischem Wissen raten – das Ergebnis sieht aus wie das Richtige, funktioniert aber in der Praxis nicht</li><li><strong>Gute Idee ist nicht gleich gutes Produkt</strong>: Sie denken, &quot;AI-Generierung hinzufügen&quot; sei cool, aber Nutzer brauchen es vielleicht gar nicht, oder es ist umständlicher als zuvor</li></ul><p><strong>Deshalb müssen wir lernen: &quot;Von der Idee zum Nutzer-Verständnis.&quot;</strong> Nur wenn Ihre Kreativität wirklich fremde Probleme löst – durch Fragen und tiefes Geschäftsverständnis – können Sie wirklich Wertvolles schaffen. (Gute Ideen sind sogar wichtiger als gute Technik.)</p><h3 id="_1-1-von-der-vorstellung-zur-realitat-lernen-das-geschaft-zu-befragen" tabindex="-1">1.1 Von der Vorstellung zur Realität: Lernen, das Geschäft zu befragen <a class="header-anchor" href="#_1-1-von-der-vorstellung-zur-realitat-lernen-das-geschaft-zu-befragen" aria-label="Permalink to “1.1 Von der Vorstellung zur Realität: Lernen, das Geschäft zu befragen”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Zunächst klären: Was ist eine Anforderung? Was ist ein Geschäft?</p><p><strong>Anforderung</strong> ist das, was Nutzer wirklich wollen – ihre Probleme, die sie lösen möchten. Zum Beispiel &quot;Der Chef will, dass ich Produkte schneller einstelle&quot; – das ist eine Anforderung.</p><p><strong>Geschäft</strong> ist das, was Nutzer täglich tun – ihre Arbeitsweise. Zum Beispiel E-Commerce-Operations: Produkte einstellen, Preise ändern, Bilder erstellen, Daten analysieren... Das alles ist Geschäft.</p><p><strong>Warum sich fürs Geschäft interessieren?</strong> Weil Ihr Tool sonst &quot;gut aussieht, aber niemand nutzt&quot;. Nur wenn Sie wirklich verstheen, wie Nutzer täglich arbeiten und wo sie feststecken, können Sie etwas bauen, das ihnen wirklich hilft.</p></div><p>Aus der einfachsten Perspektive können Sie sich zunächst folgende Fragen stellen:</p><ul><li>Der Chef sagt &quot;<strong>etwas effizienter</strong>&quot; – was genau heißt das? <strong>Schneller</strong> machen? <strong>Geld sparen</strong>? <strong>Mehr verkaufen</strong>?</li><li>Wie werden Produkte aktuell eingestellt? <strong>Wo läuft es nicht rund</strong>?</li><li>Wie viele <strong>neue Produkte</strong> gibt es täglich? Wie viele <strong>Bilder</strong> und <strong>Texte</strong> pro Produkt?</li><li>Was ist <strong>am nervigsten</strong>, was <strong>möchte man am wenigsten tun</strong>?</li></ul><p>Das sind jedoch nur Vermutungen. Wir müssen direkt mit dem Douyin E-Commerce-Operations-Team sprechen: &quot;Wo liegen eure Schwierigkeiten und worauf achtet ihr?&quot; Durch Kommunikation erhalten wir präzisere Antworten:</p><div class="info custom-block"><p class="custom-block-title">Echte Geschäftsbefragungsergebnisse</p><p>Wir haben E-Commerce-Operations-Mitarbeiter gefragt. Sie berichteten folgende Probleme:</p><p><strong>1. Zu viele Aufgaben, zu unübersichtlich</strong></p><ul><li>Eine Person muss mehrere Shops betreuen, jeder Shop hat viele Produkte</li><li>Täglich hin- und herhetzen: <strong>Neue Produkte einstellen</strong>, <strong>Preise ändern</strong>, <strong>Bilder erstellen</strong>, <strong>Daten analysieren</strong> – eine Sache ist noch nicht fertig, die nächste ruft</li></ul><p><strong>2. Inhalte werden nicht auf einmal erstellt, sondern iterativ</strong></p><ul><li>Zunächst <strong>Herstellerbilder</strong>, <strong>frühere Materialien</strong> oder <strong>Referenzbilder aus dem Web</strong> verwenden, um das Produkt <strong>schnell einzustellen</strong> und zu testen</li><li>Etwas Geld für Werbung ausgeben, <strong>schauen, ob jemand kauft</strong></li><li>Nur bei <strong>gut verkäuflichen Produkten</strong> werden Bilder, Detailbeschreibungen und Videos sorgfältig erstellt</li></ul></div><p>Nach der Geschäftsbefragung sind wir voller Enthusiasmus – jetzt können wir wirklich den perfekten, geschäftsgerechten Produktprototyp erstellen! — Schon wieder falsch gedacht. Wenn wir versuchen, &quot;alle Anforderungen auf einmal zu erfüllen&quot;, wird das Produkt riesig und lässt sich im Kurs-Zeitrahmen kaum realisieren. Deshalb müssen wir weiter strukturieren und verdichten, um den wahren Kernschmerzpunkt zu identifizieren.</p><h3 id="_1-2-von-divergenz-zu-konvergenz-den-kernschmerzpunkt-des-geschafts-identifizieren" tabindex="-1">1.2 Von Divergenz zu Konvergenz: Den Kernschmerzpunkt des Geschäfts identifizieren <a class="header-anchor" href="#_1-2-von-divergenz-zu-konvergenz-den-kernschmerzpunkt-des-geschafts-identifizieren" aria-label="Permalink to “1.2 Von Divergenz zu Konvergenz: Den Kernschmerzpunkt des Geschäfts identifizieren”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Warum &quot;konvergieren&quot;? Was ist ein &quot;Schmerzpunkt&quot;?</p><p><strong>Viele Probleme, aber welches zuerst?</strong></p><p>Nutzer erzählen Ihnen vielleicht eine Reihe von Problemen: A ist nervig, B ist nervig, C ist auch nervig... Aber wenn Sie versuchen, alle auf einmal zu lösen, wird wahrscheinlich nichts richtig. Deshalb <strong>konvergieren</strong> — aus vielen Problemen das <strong>schmerzhafteste, dringendste, am besten lösbare</strong> herausgreifen und zuerst angehen.</p><p><strong>Was ist ein Schmerzpunkt?</strong> Das ist das konkrete Problem, das Nutzer <strong>am meisten nervt, am meisten Zeit kostet und am dringendsten lösen</strong> wollen. Nicht &quot;ich finde es nützlich&quot;, sondern etwas, über das Nutzer <strong>täglich klagen und bei dem jeder Durchlauf quälend ist</strong>.</p></div><p>Durch das obige Interview haben wir viele Operations-Probleme entdeckt: Unterbrechung durch Aktionen, Verwaltung mehrerer Shops, ständiges Wechseln zwischen Einstellen/Ändern/Bilderstellen/Daten...</p><p>Wenn wir versuchen, &quot;all diese Probleme zu lösen&quot;, erhalten wir ein <strong>riesiges, aber unbrauchbares</strong> Tool.</p><p>Lassen Sie uns diese Probleme kategorisieren (AI kann helfen). Es gibt grob drei Typen:</p><ol><li><strong>Rhythmus-Probleme</strong>: Wann Produkte einstellen, wann Preise anpassen</li><li><strong>Effizienz-Probleme</strong>: Wie man mehrere Shops und Produkte gleichzeitig verwaltet</li><li><strong>Content-Probleme</strong>: Wie man schnell Produktbilder und Copywriting erstellt</li></ol><p>Für unseren Kurs ist <strong>Typ 3: Content-Erstellung</strong> am besten geeignet. Aber &quot;schnell Content erstellen&quot; ist immer noch abstrakt. Fragen wir das Geschäftsteam genauer:</p><div class="info custom-block"><p class="custom-block-title">Das Geschäftsteam sagt: Content-Erstellung hat zwei schmerzhafteste Stellen</p><p><strong>Schmerz 1: Batch-Bilderstellung und Copywriting sind extrem mühsam</strong></p><ul><li>Materialien überall verteilt: Cloud-Speicher, WeChat-Verlauf, Plattform-Backend... <strong>Schwer zu finden</strong></li><li>Viele Produkte gleichzeitig einstellen, <strong>keine Zeit für sorgfältige Erstellung</strong>, nur schnell zusammenstellen</li><li>Anspruch nicht hoch: <strong>Sichtbar und einstellbar</strong> reicht, muss nicht schick sein</li></ul><p><strong>Schmerz 2: Gute Lösungen können nicht gespeichert und wiederverwendet werden</strong></p><ul><li>Früher gute Titel und Layouts: <strong>Beim nächsten Mal nicht mehr auffindbar</strong></li><li>Lösungen verstreut in Chat-Verläufen und alten Produkt-Links</li><li>Wenn man sie braucht: <strong>Halben Tag suchen, kopieren, ändern</strong></li><li>Es fehlt ein Tool zum <strong>Sammeln, Verwalten und direkten Wiederverwenden</strong></li></ul></div><p>Basierend auf diesen beiden Schmerzpunkten erstellen wir ein einfaches kleines Tool: <strong>Operations-Team bei Batch-Bilderstellung und Copywriting helfen, plus gute Lösungen für spätere Wiederverwendung speichern</strong>.</p><p>Es macht nur zwei Dinge (lassen Sie AI bei der Detaillierung helfen, und denken Sie daran, Funktionen basierend auf Geschäfts-Feedback kontinuierlich zu reduzieren):</p><div class="info custom-block"><p class="custom-block-title">Funktion 1: Batch-generierte E-Commerce-Produktbilder und Copywriting</p><p><strong>Was macht das?</strong> Dem System Produktinformationen geben, und es generiert automatisch Produktbilder und Texte, die auf E-Commerce-Plattformen (wie Douyin, Taobao) eingestellt werden können.</p><p><strong>Eingabe</strong></p><table tabindex="0"><thead><tr><th>Typ</th><th>Inhalt</th></tr></thead><tbody><tr><td>Produktinformationen</td><td>Name, Kategorie, Marke, Material, Größe, Farbe etc.</td></tr><tr><td>Produktbilder</td><td>Weißgrund oder einfaches Szenario-Foto</td></tr><tr><td>Referenzbilder</td><td>Screenshots früherer Bestseller oder Referenz-Links</td></tr><tr><td>Import-Methode</td><td>Excel Batch-Import oder direkt auf der Seite ausfüllen</td></tr></tbody></table><p><strong>Ausgabe (generierte E-Commerce-Materialien)</strong></p><ul><li><strong>Produkt-Hauptbild</strong>: Produktansicht mit Text-Selling-Points (das Bild, das Nutzer beim Scrollen zuerst sehen)</li><li><strong>Produkttitel</strong>: Keyword-Kombination, die bei der Suche gefunden wird</li><li><strong>Selling-Point-Copywriting</strong>: 1-2 Sätze, die Käufer anziehen</li><li>Alles <strong>nach kleiner Korrektur einstellbar</strong></li></ul><p><strong>Ergebnis</strong></p><ul><li>Früher: Jedes Produkt von Grund auf neu erstellen</li><li>Jetzt: Eine Charge Produkte ins System geben, Entwürfe generieren, auswählen und nachbessern</li></ul></div><div class="info custom-block"><p class="custom-block-title">Funktion 2: Gute Lösungen als Vorlagen speichern</p><p><strong>Eingabe</strong></p><table tabindex="0"><thead><tr><th>Typ</th><th>Inhalt</th></tr></thead><tbody><tr><td>Ein kompletter Satz</td><td>Hauptbild + Titel + Copywriting</td></tr></tbody></table><p><strong>Ausgabe</strong></p><table tabindex="0"><thead><tr><th>Funktion</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Anwenden</td><td>Beim nächsten neuen Produkt die Vorlage automatisch anwenden</td></tr><tr><td>Bearbeiten</td><td>Titel und Copywriting direkt ändern</td></tr><tr><td>Verwalten</td><td>Benennen, taggen (z.B. &quot;Herrentaschen-Vorlage&quot;, &quot;Großverkaufs-Titel&quot;), leicht auffindbar</td></tr></tbody></table><p><strong>Ergebnis</strong></p><ol><li>Neues Produkt importieren</li><li>Auswählen: Systemstandard-Generierung oder <strong>meine gespeicherte Vorlage verwenden</strong></li><li>System wendet automatisch Vorlagen-Stil an und generiert neue Bilder und Copywriting</li></ol></div><hr><p><strong>Rückblick auf das, was wir gerade getan haben:</strong></p><ol><li><strong>Zuerst Fragen stellen</strong>: Nicht direkt mit dem Programmieren beginnen, sondern zuerst das Operations-Team fragen &quot;Was nervt euch am meisten&quot;</li><li><strong>Schmerzpunkte finden</strong>: Entdeckt, dass sie am meisten unter &quot;Bilder und Copywriting erstellen ist zu mühsam&quot; und &quot;gute Lösungen können nicht gespeichert werden&quot; leiden</li><li><strong>Umfang eingrenzen</strong>: Keine allesumfassende Plattform bauen, sondern nur &quot;Batch-Generierung von Bildern und Copywriting + Vorlagen speichern&quot; – diese beiden Funktionen</li></ol><p><strong>Warum ist das so wichtig?</strong></p><p>Ein häufiger Fehler von Anfängern bei der Produktentwicklung ist: Mehr Funktionen ist besser. Aber was Nutzer wirklich brauchen, ist <strong>die Lösung des schmerzhaftesten Problems</strong>. Eine Reihe von Funktionen, die alle nicht richtig funktionieren, ist schlechter als ein bis zwei Funktionen, die Nutzer wirklich unterstützen.</p><p><strong>Kern des Produkt- und Geschäftsdenkens:</strong></p><ul><li>Nicht selbst denken &quot;Ich glaube, Nutzer brauchen das&quot;</li><li>Nutzer fragen &quot;Was machst du jeden Tag? Wo tut es am meisten weh?&quot;</li><li>Aus einer Menge von Problemen <strong>konvergieren</strong> auf das schmerzhafteste, am besten lösbare</li><li>Zuerst die <strong>minimal nutzbare</strong> Version erstellen, dann schrittweise iterieren</li></ul><p>Das ist es, was wir klären müssen, bevor wir Code schreiben. Code ist nur ein Werkzeug – <strong>Nutzer verstheen, das richtige Problem finden</strong> ist der erste Schritt.</p>`,35)),e("div",F,[s(o,null,{default:t(()=>[s(l,{active:1,items:[{title:"Anforderungsanalyse",description:"Von vage zu konkret"},{title:"Single-Page-Validierung",description:"Kernfunktion implementieren"},{title:"Multi-Page-Erweiterung",description:"Anwendungsstruktur vervollständigen"},{title:"Optimierung",description:"Nutzererfahrung verbessern"}]})]),_:1})]),n[10]||(n[10]=a(`<h2 id="_2-in-10-minuten-einen-prototyp-erstellen-ai-ide-lasst-die-kernfunktion-wirklichkeit-werden" tabindex="-1">2. In 10 Minuten einen Prototyp erstellen: AI IDE lässt die &quot;Kernfunktion&quot; Wirklichkeit werden <a class="header-anchor" href="#_2-in-10-minuten-einen-prototyp-erstellen-ai-ide-lasst-die-kernfunktion-wirklichkeit-werden" aria-label="Permalink to “2. In 10 Minuten einen Prototyp erstellen: AI IDE lässt die &quot;Kernfunktion&quot; Wirklichkeit werden”">​</a></h2><div class="info custom-block"><p class="custom-block-title">Programmier-Plan-Empfehlung</p><p>Wenn Sie das Gefühl haben, dass Ihre aktuelle IDE nicht intelligent genug ist oder Ihr Kontingent schnell aufgebraucht ist, können Sie einen <strong>Programmier-Plan</strong> erwerben. Zur Vorbereitung lesen Sie <a href="./../../stage-2/backend/modern-cli/">diesen Artikel</a> über die Verwendung von Claude zum Programmieren.</p></div><p>Nachdenken ist gut, aber man sollte nicht übermäßig reflektieren. Wir steuern die übermäßige Reflexion und versuchen, mit einer einzelnen Seite einen Prototyp zu erstellen.</p><h3 id="_2-1-erster-schritt-ai-in-einfachen-worten-sagen-was-sie-wollen" tabindex="-1">2.1 Erster Schritt: AI in einfachen Worten sagen, was Sie wollen <a class="header-anchor" href="#_2-1-erster-schritt-ai-in-einfachen-worten-sagen-was-sie-wollen" aria-label="Permalink to “2.1 Erster Schritt: AI in einfachen Worten sagen, was Sie wollen”">​</a></h3><p>Am Anfang müssen Sie keine perfekten Prompts anstreben. Beginnen Sie mit Ihrem natürlichsten Ausdruck. Beschreiben Sie AI wie einem Kollegen Ihre Anforderungen in einfachen Worten, und lassen Sie AI Ihnen helfen, sie in einen professionelleren Ausdruck zu optimieren.</p><h4 id="_2-1-1-mit-einer-mundlichen-beschreibung-beginnen-empfohlen-fur-anfanger" tabindex="-1">2.1.1 Mit einer mündlichen Beschreibung beginnen (empfohlen für Anfänger) <a class="header-anchor" href="#_2-1-1-mit-einer-mundlichen-beschreibung-beginnen-empfohlen-fur-anfanger" aria-label="Permalink to “2.1.1 Mit einer mündlichen Beschreibung beginnen (empfohlen für Anfänger)”">​</a></h4><p>Beschreiben Sie Ihre Idee zuerst in Ihren eigenen Worten – auch wenn es noch so rau ist:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ich möchte ein Tool erstellen, das E-Commerce-Operations-Mitarbeitern hilft,</span></span>
<span class="line"><span>automatisch Produkt-Hauptbilder und Copywriting zu generieren.</span></span>
<span class="line"><span>Operations-Mitarbeiter müssen aktuell manuell Bild für Bild und Text für Text</span></span>
<span class="line"><span>erstellen, was sehr mühsam ist.</span></span>
<span class="line"><span>Meine Idee: Sie laden Produktinformationen hoch, das System generiert automatisch</span></span>
<span class="line"><span>einen Satz Entwürfe, die Operations-Mitarbeiter wählen die brauchbaren aus,</span></span>
<span class="line"><span>ändern sie leicht und können sie verwenden.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Zuerst die einfachste Version: eine Seite, links Produktinformationen eingeben,</span></span>
<span class="line"><span>rechts die generierten Ergebnisse anzeigen. Bilder hochladen, Text eingeben,</span></span>
<span class="line"><span>nach der Generierung Hauptbild-Vorschau und Copywriting anzeigen.</span></span></code></pre></div><p>Senden Sie diesen Text dann an eine AI (wie ChatGPT, Claude etc.), damit sie ihn für Sie erweitert. AI hilft Ihnen normalerweise dabei, Details zu ergänzen, an die Sie noch nicht gedacht haben, Ihre Ideen klarer zu strukturieren und schließlich einen Prompt zu generieren, der sich für AI IDE eignet.</p><p>Sie können AI so ansprechen:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hilf mir, die obige Idee zu erweitern und in ein klares</span></span>
<span class="line"><span>Geschäftslogik-Dokument zu strukturieren. Generiere dann einen Prompt,</span></span>
<span class="line"><span>der sich für AI IDE (wie Cursor, Trae) eignet, um Single-Page-Prototyp-Code</span></span>
<span class="line"><span>zu generieren.</span></span></code></pre></div><p>AI wird eine strukturierte Anforderung und den entsprechenden Prompt zurückgeben. Überprüfen Sie diese selbst, entfernen Sie unnötige Funktionen und bestätigen Sie sie, bevor Sie den Code generieren.</p><p>Der Vorteil dieses Ansatzes: Die mündliche Beschreibung enthält die authentischsten Ideen, kann aber wichtige Details übersehen. Wenn AI für Sie erweitert, könnte sie Fragen stellen wie &quot;Soll Batch-Upload unterstützt werden?&quot;, an die Sie noch nicht gedacht haben. So können Sie Ihre Anforderungen weiter validieren. Sie können basierend auf dem Feedback entscheiden, ob Sie unpraktische Funktionen beibehalten oder entfernen möchten, und durch wiederholte Überarbeitung den ersten Prompt für AI festlegen.</p><h4 id="_2-1-2-den-erweiterungsschritt-uberspringen-geschaftsdokument-direkt-an-ai-ubergeben" tabindex="-1">2.1.2 Den Erweiterungsschritt überspringen: Geschäftsdokument direkt an AI übergeben <a class="header-anchor" href="#_2-1-2-den-erweiterungsschritt-uberspringen-geschaftsdokument-direkt-an-ai-ubergeben" aria-label="Permalink to “2.1.2 Den Erweiterungsschritt überspringen: Geschäftsdokument direkt an AI übergeben”">​</a></h4><p>Wenn Sie in den vorherigen Kapiteln bereits ein Geschäftslogik-Dokument erstellt haben (z.B. eine in einfachen Worten verfasste Anforderungsbeschreibung), können Sie das folgende Format direkt verwenden und an AI IDE senden – ohne den Zwischenschritt der AI-Erweiterung. Dies eignet sich, wenn die Anforderungen bereits klar sind und Sie direkt mit dem Programmieren beginnen möchten:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hilf mir, basierend auf der Geschäftslogik eine Single-Page-Anwendung</span></span>
<span class="line"><span>zu implementieren, um die Kernfunktion zu validieren.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Geschäftslogik-Referenz:</span></span>
<span class="line"><span>1. Operations-Mitarbeitern helfen, die erste Version von Bild- und Textentwürfen</span></span>
<span class="line"><span>   stapelweise zu generieren:</span></span>
<span class="line"><span>- **Eingabe (direkter Upload und Batch-Import unterstützt):**</span></span>
<span class="line"><span>  - Produktbasisinformationen: Name, Kategorie, Marke, Material, Größe, Farbe,</span></span>
<span class="line"><span>    Zielgruppe etc.;</span></span>
<span class="line"><span>  - Produktbilder: Weißgrund / einfaches Szenario-Foto;</span></span>
<span class="line"><span>  - Bei jeder Generierung: zusätzlicher Upload von Screenshots früherer</span></span>
<span class="line"><span>    Bestseller oder Referenz-Links möglich;</span></span>
<span class="line"><span>  - Excel Batch-Import oder Online-Eingabe/Upload auf der Seite unterstützt.</span></span>
<span class="line"><span>  - Auf der Seite kann angegeben werden, ob Produktmaterialien in der</span></span>
<span class="line"><span>    Materialbibliothek gespeichert werden sollen, für spätere Verwendung.</span></span>
<span class="line"><span>- **Ausgabe (Inhalte, die direkt oder mit leichten Änderungen eingestellt</span></span>
<span class="line"><span>  werden können):**</span></span>
<span class="line"><span>  - Für jedes Produkt ein Hauptbild-Entwurf, der &quot;ansehbar&quot; ist und</span></span>
<span class="line"><span>    grundlegende Selling-Points enthält;</span></span>
<span class="line"><span>  - Ein &quot;strukturgerechter&quot; Titel mit Kern-Keywords + 1-2 Sätze</span></span>
<span class="line"><span>    Selling-Point-Copywriting.</span></span>
<span class="line"><span>- **Erwartete Änderung der Arbeitsweise:**</span></span>
<span class="line"><span>  Vom Neuentwurf für jede Produktcharge zum Einwerfen einer Charge in das</span></span>
<span class="line"><span>  System, mit System-Entwürfen zur Auswahl und Feinjustierung.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Zuerst die erste Funktion implementieren, die zweite Funktion (Vorlagenbibliothek)</span></span>
<span class="line"><span>wird später hinzugefügt.</span></span></code></pre></div><h4 id="_2-1-3-der-programmierer-ansatz-fortgeschritten-ai-helfen-lassen-einen-prompt-fur-prompts-zu-schreiben" tabindex="-1">2.1.3 Der Programmierer-Ansatz (fortgeschritten): AI helfen lassen, einen &quot;Prompt für Prompts&quot; zu schreiben <a class="header-anchor" href="#_2-1-3-der-programmierer-ansatz-fortgeschritten-ai-helfen-lassen-einen-prompt-fur-prompts-zu-schreiben" aria-label="Permalink to “2.1.3 Der Programmierer-Ansatz (fortgeschritten): AI helfen lassen, einen &quot;Prompt für Prompts&quot; zu schreiben”">​</a></h4><p>Wenn Sie den Code-Generierungsprozess feiner steuern möchten, können Sie zuerst AI (wie ChatGPT) bitten, basierend auf Ihren Anforderungen einen speziell für AI IDE bestimmten Prompt zu generieren:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Basierend auf der folgenden Idee, hilf mir, einen Prompt für einen Coding Agent</span></span>
<span class="line"><span>zu schreiben, um Code zu generieren. Ich muss diesen Prompt verwenden, um Code</span></span>
<span class="line"><span>zu erstellen.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Deine Geschäftslogik-Beschreibung hier einfügen]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Anforderungen:</span></span>
<span class="line"><span>1. Der Prompt soll eine klare Seitenlayout-Beschreibung enthalten</span></span>
<span class="line"><span>2. Datenstrukturen und Interaktionslogik klar definieren</span></span>
<span class="line"><span>3. Technology Stack angeben (z.B. React + Tailwind)</span></span>
<span class="line"><span>4. Die zu implementierenden Kernfunktionen auflisten</span></span></code></pre></div><p>Normalerweise generiert AI einen strukturierten Prompt wie den folgenden: <img src="`+b+'" alt=""></p><p>Sie können diesen Prompt nach kleinen Anpassungen an AI IDE senden, um Code zu generieren.</p><h3 id="_2-2-zweiter-schritt-ai-ide-direkt-code-generieren-lassen" tabindex="-1">2.2 Zweiter Schritt: AI IDE direkt Code generieren lassen <a class="header-anchor" href="#_2-2-zweiter-schritt-ai-ide-direkt-code-generieren-lassen" aria-label="Permalink to “2.2 Zweiter Schritt: AI IDE direkt Code generieren lassen”">​</a></h3><h4 id="_2-2-1-vorbereitung-grundlegende-bedienung-von-ai-ide-verstheen" tabindex="-1">2.2.1 Vorbereitung: Grundlegende Bedienung von AI IDE verstheen <a class="header-anchor" href="#_2-2-1-vorbereitung-grundlegende-bedienung-von-ai-ide-verstheen" aria-label="Permalink to “2.2.1 Vorbereitung: Grundlegende Bedienung von AI IDE verstheen”">​</a></h4><p>Wenn Sie mit AI IDE (wie Cursor, Trae, Windsurf etc.) noch nicht vertraut sind, empfehlen wir, zunächst das <a href="/easy-vibe-ja-learning-map/zh-cn/appendix/2-development-tools/ide-basics/">IDE-Grundlagen-Tutorial</a> im Anhang zu lesen, um zu erfahren:</p><ul><li>Wie man ein neues Projekt erstellt</li><li>Wie man mit dem AI Agent kommuniziert</li><li>Wie man den Code-Generierungsprozess der AI versthet</li></ul><h4 id="_2-2-2-mit-der-code-generierung-beginnen" tabindex="-1">2.2.2 Mit der Code-Generierung beginnen <a class="header-anchor" href="#_2-2-2-mit-der-code-generierung-beginnen" aria-label="Permalink to “2.2.2 Mit der Code-Generierung beginnen”">​</a></h4><p>Jetzt haben Sie den initialen Prompt erhalten. Wir nehmen den ersten Prompt-Stil als Beispiel und lassen AI uns beim Generieren von Code helfen. Erstellen Sie zuerst ein Fenster und den entsprechenden Ordner, öffnen Sie den Ordner (initialisieren Sie ein neues Projekt in Ihrem bevorzugten Ordner): <img src="'+f+'" alt=""><img src="'+k+'" alt=""></p><p>Wählen Sie in der Seitenleiste ein Modell Ihrer Wahl (empfohlen: gemini, gpt, glm, kimi, minimax etc.) und geben Sie den Prompt aus dem ersten Schritt ein: <img src="'+w+'" alt=""></p><p>Nach dem Klick auf Generieren sehen wir den vertrauten Vorgang: AI plant basierend auf dem Prompt die Verzeichnisstruktur des Projekts, die notwendigen Dateien und gibt den ursprünglichen Inhalt jeder Datei an.</p><div class="warning custom-block"><p class="custom-block-title">Wichtiger Hinweis: AI kann anhalten und auf Ihre Bestätigung warten</p><p>Während des Generierungsprozesses hält der <strong>AI Agent oft an und wartet auf Ihre Eingabe oder Bestätigung</strong>, zum Beispiel:</p><ul><li>Fragt Sie, ob Sie mit dem nächsten Schritt fortfahren möchten</li><li>Bittet Sie, die Eingabetaste zu drücken, um eine Aktion zu bestätigen</li><li>Fragt Sie nach der Wahl eines technischen Details</li></ul><p><strong>Wenn AI nicht mehr reagiert, prüfen Sie zuerst die Dialogoberfläche, ob sie auf Ihre Antwort wartet.</strong> Viele Anfänger denken, AI würde noch nachdenken, aber sie hat bereits angehalten und wartet auf Sie. Aktiv antworten oder Eingabetaste drücken, dann arbeitet AI weiter.</p></div><p>Vergessen Sie auch hier nicht, die Eingabetaste zu drücken, um die Informationen zu bestätigen (andernfalls geraten Sie in eine Warteschleife; einige AI IDEs haben dieses Problem nicht): <img src="'+z+'" alt=""></p><p>Wenn Sie die folgende Szene sehen, bedeutet das, dass bereits ein lokaler Dienst gestartet wurde. Sie müssen auf Überspringen klicken, sonst bleiben Sie auf dieser Oberfläche (wenn nach der Code-Generierung nichts erscheint, müssen Sie aktiv sagen: &quot;Hilf mir, dieses Projekt zu starten&quot;): <img src="'+S+'" alt=""></p><div class="info custom-block"><p class="custom-block-title">Szenario-Erklärung</p><p><strong>Szenario-Beschreibung</strong>: Sie haben mit <code>npm create vite@latest</code> ein React + TypeScript-Projekt (easy-vibe-web) erstellt. Nach Abschluss der Erstellung startet Ihr Computer automatisch die Webseite, damit Sie das Ergebnis sofort sehen können.</p><p><strong>Lokaler Dienst</strong>: Kann als temporäres Webseiten-Anzeigefenster auf Ihrem Computer verstanden werden, das nur auf Ihrem eigenen Rechner läuft und für andere nicht zugänglich ist.</p><p><strong>localhost (lokale Adresse)</strong>: <code>localhost</code> bedeutet &quot;dieser Computer selbst&quot;. Wenn Sie im Browser darauf zugreifen, greifen Sie tatsächlich auf die Webseite zu, die auf Ihrem Computer läuft.</p><p><strong>Port</strong>: Ein Port kann als Nummer verstanden werden, die verschiedene Webdienste auf demselben Computer unterscheidet. Dieses Projekt verwendet 5174.</p><p><strong>Zugriffslink <code>http://localhost:5174/</code></strong>: Diese Adresse bedeutet &quot;Zugriff auf die Webseite mit der Nummer 5174 auf diesem Computer&quot;. Im Browser öffnen, um das Ergebnis zu sehen.</p><p><strong>Aktuelle Szenario-Erklärung</strong>: Das System wollte ursprünglich 5173 verwenden, aber diese Nummer war bereits belegt, daher wurde automatisch auf 5174 gewechselt. Das ist normal.</p><p><strong>Bedienungsanleitung</strong>: Öffnen Sie den Browser, geben Sie <code>http://localhost:5174/</code> in die Adressleiste ein und drücken Sie Enter, um die aktuelle Projektseite zu sehen.</p></div><p>Nachdem alles bestätigt ist, warten Sie einen Moment, bis der Agent seine Arbeit beendet hat. Wir erhalten folgendes Ergebnis: <img src="'+v+'" alt=""></p><p>Man sieht bereits eine erste funktionale Ansicht, aber das Frontend sieht noch sehr unschön aus. Jetzt können wir versuchen, direkt mit AI zu dialogieren und die Oberfläche zu optimieren: <img src="'+P+'" alt=""></p><p>Nach der Optimierung erhalten wir eine deutlich ansprechendere Oberfläche: <img src="'+A+'" alt=""></p><p>Sie können die Webseiten-Funktionen nach Ihren eigenen Bedürfnissen anpassen, Screenshots anhängen und frei Fragen stellen, wie zum Beispiel: &quot;Ich brauche die Batch-Import-Funktion derzeit nicht, bitte entfernen&quot;, &quot;Links muss zu viel eingegeben werden, behalte nur xxxxx&quot;. Sie können sogar andere ausgereifte Websites als Referenz heranziehen – hier können wir direkt ein Design-Produkt von Google als &quot;Referenz&quot; verwenden (Sie können einen Screenshot einer ausgereiften Website einfügen, die Ihnen gefällt): <img src="'+I+'" alt=""></p><p>Schließlich erhalten wir: <img src="'+E+'" alt=""></p><h3 id="_2-3-was-tun-bei-fehlern" tabindex="-1">2.3 Was tun bei Fehlern <a class="header-anchor" href="#_2-3-was-tun-bei-fehlern" aria-label="Permalink to “2.3 Was tun bei Fehlern”">​</a></h3><p>In der Praxis sind Fehler unvermeidlich. Das ist normal und bedeutet nicht, dass Sie etwas falsch gemacht haben. Sie müssen die Fehler nicht verstheen – geben Sie einfach das &quot;Was Sie sehen&quot; vollständig an AI weiter.</p><p>Es gibt grundsätzlich drei Behandlungsmethoden:</p><ul><li><p><strong>Methode 1: Seiten- oder Terminal-Fehler</strong> Wenn die Seite rot wird, weiß wird oder im Terminal viele rote Zeilen erscheinen, machen Sie einen Screenshot oder kopieren Sie die gesamte Fehlermeldung und senden Sie sie an AI, damit sie Ihnen bei der Reparatur hilft.</p></li><li><p><strong>Methode 2: Funktion falsch, aber kein Fehler</strong> Zum Beispiel reagiert ein Button nicht, Daten werden nicht angezeigt, das Layout ist durcheinander. Beschreiben Sie in einfachen Worten &quot;Was gerade passiert + Was Sie eigentlich wollen&quot;, bei Bedarf mit einem Screenshot.</p></li><li><p><strong>Methode 3: Unsicher, ob es ein Problem gibt</strong> Sie können AI direkt fragen: &quot;Hilf mir zu prüfen, ob diese Funktion offensichtliche Probleme hat und ob sie angepasst werden muss.&quot;</p></li></ul><h4 id="_2-3-1-haufige-fragen-von-anfangern" tabindex="-1">2.3.1 Häufige Fragen von Anfängern <a class="header-anchor" href="#_2-3-1-haufige-fragen-von-anfangern" aria-label="Permalink to “2.3.1 Häufige Fragen von Anfängern”">​</a></h4><ul><li><p><strong>F: Ich weiß nicht, wo die Fehlermeldung ist?</strong></p></li><li><p>A: Suchen Sie grundsätzlich nach allem, was &quot;rot&quot; ist. Im Terminal, in der Konsole oder auf der Seite – finden Sie die roten Hinweise, markieren Sie alles und kopieren Sie es zu AI.</p></li><li><p><strong>F: AI hat es repariert, aber es kommt derselbe Fehler – was nun?</strong></p></li><li><p>A: Das ist ein häufiges Szenario. Machen Sie weiterhin Screenshots oder kopieren Sie die neueste Fehlermeldung und senden Sie sie an AI, damit sie auf Basis der letzten Änderung weiter repariert.</p></li><li><p><strong>F: Muss ich AI&#39;s Reparaturansatz vollständig verstheen?</strong></p></li><li><p>A: Nicht auf einmal. Konzentrieren Sie sich jedes Mal auf ein bis zwei Punkte. Mit der Zeit werden Sie zunehmend mehr Code verstheen – wie beim Aufbau eines englischen Wortschatzes.</p></li><li><p><strong>F: Viele Male geändert, das Problem ist immer noch nicht gelöst – was nun?</strong></p></li><li><p>A: Sie können Folgendes versuchen:</p><ul><li>Die &quot;Versionsrücksetzung&quot;-Funktion der IDE verwenden. Im Agent-Dialog den Rückgängig-Button finden und zu einer lauffähigen Version zurückkehren und neu beginnen;</li><li>Ein anderes Modell wählen oder den Prompt anpassen, Phänomene und Fehlermeldungen spezifischer beschreiben;</li><li>&quot;Aktuellen Code + Fehler-Log + erwartetes Verhalten&quot; zusammenpacken und AI auf einmal übergeben, damit sie den Problembereich insgesamt restrukturiert.</li></ul></li></ul><h2 id="_3-von-der-single-page-zur-multi-page-anwendung-erweitern" tabindex="-1">3. Von der Single-Page zur Multi-Page-Anwendung erweitern <a class="header-anchor" href="#_3-von-der-single-page-zur-multi-page-anwendung-erweitern" aria-label="Permalink to “3. Von der Single-Page zur Multi-Page-Anwendung erweitern”">​</a></h2>',45)),e("div",M,[s(o,null,{default:t(()=>[s(l,{active:2,items:[{title:"Anforderungsanalyse",description:"Von vage zu konkret"},{title:"Single-Page-Validierung",description:"Kernfunktion implementieren"},{title:"Multi-Page-Erweiterung",description:"Anwendungsstruktur vervollständigen"},{title:"Optimierung",description:"Nutzererfahrung verbessern"}]})]),_:1})]),n[11]||(n[11]=a('<p>Wenn die Logik der Kernfunktion grundsätzlich generiert ist, können wir die restlichen Inhalte erstellen. Zum Beispiel sind Klicks auf Einstellungen oder bestimmte Buttons zu diesem Zeitpunkt noch völlig wirkungslos.</p><p>Sie können AI bitten, basierend auf den Anforderungen des Geschäftsprompts zu prüfen und die noch nicht generierten Teile zu erstellen. Oder Sie lassen AI die nicht vollständig implementierten Seiten direkt ergänzen. Sie können auch eine bestimmte Seite angeben, die AI implementieren soll, bis alle Seiten klickbar und alle Funktionen ordnungsgemäß interaktiv sind: <img src="'+y+'" alt=""></p><p>Nach kurzer Wartezeit sehen wir, dass das Programm auf der bisherigen Basis mehrere Seiten und interaktive Funktionen ergänzt hat: <img src="'+_+'" alt=""></p><p><img src="'+q+'" alt=""></p><p>Jetzt müssen Sie nur noch manuell jede Funktion und jeden Button anklicken, die Sie interessieren, und sicherstellen, dass die Interaktion ordnungsgemäß funktioniert. Wenn es nicht interaktive Funktionen gibt, können Sie mit AI kommunizieren und sie um Hilfe bei der Reparatur bitten.</p><h2 id="_4-den-prototyp-wie-echt-aussehen-lassen" tabindex="-1">4. Den Prototyp &quot;wie echt&quot; aussehen lassen <a class="header-anchor" href="#_4-den-prototyp-wie-echt-aussehen-lassen" aria-label="Permalink to “4. Den Prototyp &quot;wie echt&quot; aussehen lassen”">​</a></h2>',6)),e("div",N,[s(o,null,{default:t(()=>[s(l,{active:3,items:[{title:"Anforderungsanalyse",description:"Von vage zu konkret"},{title:"Single-Page-Validierung",description:"Kernfunktion implementieren"},{title:"Multi-Page-Erweiterung",description:"Anwendungsstruktur vervollständigen"},{title:"Optimierung",description:"Nutzererfahrung verbessern"}]})]),_:1})]),n[12]||(n[12]=a(`<p>Nachdem wir die Multi-Page-Struktur haben, ist der letzte Schritt, den Prototyp von &quot;es läuft&quot; zu &quot;lässt sich flüssig bedienen und sieht professionell aus&quot; zu bringen. Dafür müssen wir den gesamten Prozess (Nutzer-Flow) einmal selbst durchlaufen und die nicht funktionierenden Teile von AI reparieren lassen, damit wir nach jedem Refresh den vollständigen Prozess als neuer Nutzer simulieren und die erwarteten Ergebnisse erhalten können.</p><p>Lassen Sie uns die ursprünglichen Anforderungen rekapitulieren:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. Operations-Mitarbeitern helfen, die erste Version von Bild- und Textentwürfen</span></span>
<span class="line"><span>   stapelweise zu generieren:</span></span>
<span class="line"><span>- **Eingabe (direkter Upload und Batch-Import unterstützt):**</span></span>
<span class="line"><span>  - Produktbasisinformationen: Name, Kategorie, Marke, Material, Größe, Farbe,</span></span>
<span class="line"><span>    Zielgruppe etc.;</span></span>
<span class="line"><span>  - Produktbilder: Weißgrund / einfaches Szenario-Foto;</span></span>
<span class="line"><span>  - Bei jeder Generierung: zusätzlicher Upload von Screenshots früherer</span></span>
<span class="line"><span>    Bestseller oder Referenz-Links möglich;</span></span>
<span class="line"><span>  - Excel Batch-Import oder Online-Eingabe/Upload auf der Seite unterstützt.</span></span>
<span class="line"><span>  - Auf der Seite kann angegeben werden, ob Produktmaterialien in der</span></span>
<span class="line"><span>    Materialbibliothek gespeichert werden sollen, für spätere Verwendung.</span></span>
<span class="line"><span>- **Ausgabe (Inhalte, die direkt oder mit leichten Änderungen eingestellt</span></span>
<span class="line"><span>  werden können):**</span></span>
<span class="line"><span>  - Für jedes Produkt ein Hauptbild-Entwurf, der &quot;ansehbar&quot; ist und</span></span>
<span class="line"><span>    grundlegende Selling-Points enthält;</span></span>
<span class="line"><span>  - Ein &quot;strukturgerechter&quot; Titel mit Kern-Keywords + 1-2 Sätze</span></span>
<span class="line"><span>    Selling-Point-Copywriting.</span></span>
<span class="line"><span>- **Erwartete Änderung der Arbeitsweise:**</span></span>
<span class="line"><span>  Vom Neuentwurf für jede Produktcharge zum Einwerfen einer Charge in das</span></span>
<span class="line"><span>  System, mit System-Entwürfen zur Auswahl und Feinjustierung.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Gute Outputs als wiederverwendbare Vorlagenbibliothek konservieren:</span></span>
<span class="line"><span>- **Was kann gespeichert werden?**</span></span>
<span class="line"><span>  - Jeder Output, von dem der Operations-Mitarbeiter findet, dass er &quot;gut</span></span>
<span class="line"><span>    funktioniert&quot;, kann mit einem Klick gespeichert werden:</span></span>
<span class="line"><span>    - Kann eine komplette Kombination aus &quot;Hauptbild + Titel + Selling-Point&quot;</span></span>
<span class="line"><span>      sein;</span></span>
<span class="line"><span>    - Oder nur ein Teil davon, z.B. eine bestimmte Titel-Struktur oder ein</span></span>
<span class="line"><span>      bestimmter Selling-Point-Text.</span></span>
<span class="line"><span>- **Was kann nach dem Speichern getan werden?**</span></span>
<span class="line"><span>  - **Wiederverwenden:**</span></span>
<span class="line"><span>    - Diese gespeicherte Vorlage verwenden, neue Produkt-Parameter einsetzen,</span></span>
<span class="line"><span>      neue Bild- und Textentwürfe generieren;</span></span>
<span class="line"><span>    - Oder auf demselben Produkt basierend auf der Vorlage mehrere Varianten</span></span>
<span class="line"><span>      für A/B-Tests generieren.</span></span>
<span class="line"><span>  - **Bearbeiten:**</span></span>
<span class="line"><span>    - Titel-Text / Selling-Point-Text direkt ändern;</span></span>
<span class="line"><span>    - Wenn Bildbearbeitung unterstützt wird, können Text, Sticker etc. im</span></span>
<span class="line"><span>      Hauptbild feinjustiert werden.</span></span>
<span class="line"><span>  - **Verwalten:**</span></span>
<span class="line"><span>    - Gespeicherte Vorlagen benennen, taggen (z.B. &quot;Herrentaschen-Hauptbild-Vorlage&quot;,</span></span>
<span class="line"><span>      &quot;Großverkaufs-Titel-Struktur&quot;), nach Shop kategorisieren für einfache</span></span>
<span class="line"><span>      spätere Suche.</span></span>
<span class="line"><span>- **Wie beim nächsten Mal verwenden?**</span></span>
<span class="line"><span>  - Nach Import eines neuen Produkts kann der Operations-Mitarbeiter wählen:</span></span>
<span class="line"><span>    - Systemstandard-Logik verwenden, oder</span></span>
<span class="line"><span>    - &quot;Meine gespeicherte Vorlage verwenden&quot; angeben;</span></span>
<span class="line"><span>  - Das System wendet basierend auf den neuen Produktdaten automatisch Struktur</span></span>
<span class="line"><span>    und Stil der Vorlage an und generiert neue Hauptbild + Titel +</span></span>
<span class="line"><span>    Selling-Point-Entwürfe.</span></span></code></pre></div><p>Wenn bei jedem Test neue Daten manuell erstellt werden müssen, kostet das viel Zeit. Zu diesem Zeitpunkt verwenden wir normalerweise eine Methode namens &quot;Testdaten&quot;. Wir können wie folgt mit AI kommunizieren und AI bitten, auf der Oberfläche einen schnellen Testdaten-Eingang zu generieren, damit wir testen können, ob alle Funktionen ordnungsgemäß durchlaufen werden:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ich muss jetzt diesen Nutzungsprozess testen und sicherstellen, dass er</span></span>
<span class="line"><span>vollständig durchlaufen werden kann. Bitte generiere basierend auf den</span></span>
<span class="line"><span>folgenden Anforderungen einen Testdaten-Eingang, damit ich nach einem Klick</span></span>
<span class="line"><span>schnell testen kann, ob der gesamte Prozess normal funktioniert:</span></span>
<span class="line"><span>1. Operations-Mitarbeitern helfen, die erste Version von Bild- und Textentwürfen</span></span>
<span class="line"><span>   stapelweise zu generieren:</span></span>
<span class="line"><span>- **Eingabe (direkter Upload und Batch-Import unterstützt):**</span></span>
<span class="line"><span>  - Produktbasisinformationen: Name, Kategorie, Marke, Material, Größe, Farbe,</span></span>
<span class="line"><span>    Zielgruppe etc.;</span></span>
<span class="line"><span>  - Produktbilder: Weißgrund / einfaches Szenario-Foto;</span></span>
<span class="line"><span>  - Bei jeder Generierung: zusätzlicher Upload von Screenshots früherer</span></span>
<span class="line"><span>    Bestseller oder Referenz-Links möglich;</span></span>
<span class="line"><span>  - Excel Batch-Import oder Online-Eingabe/Upload auf der Seite unterstützt.</span></span>
<span class="line"><span>  - Auf der Seite kann angegeben werden, ob Produktmaterialien in der</span></span>
<span class="line"><span>    Materialbibliothek gespeichert werden sollen, für spätere Verwendung.</span></span>
<span class="line"><span>- **Ausgabe (Inhalte, die direkt oder mit leichten Änderungen eingestellt</span></span>
<span class="line"><span>  werden können):**</span></span>
<span class="line"><span>  - Für jedes Produkt ein Hauptbild-Entwurf, der &quot;ansehbar&quot; ist und</span></span>
<span class="line"><span>    grundlegende Selling-Points enthält;</span></span>
<span class="line"><span>  - Ein &quot;strukturgerechter&quot; Titel mit Kern-Keywords + 1-2 Sätze</span></span>
<span class="line"><span>    Selling-Point-Copywriting.</span></span>
<span class="line"><span>- **Erwartete Änderung der Arbeitsweise:**</span></span>
<span class="line"><span>  Vom Neuentwurf für jede Produktcharge zum Einwerfen einer Charge in das</span></span>
<span class="line"><span>  System, mit System-Entwürfen zur Auswahl und Feinjustierung.</span></span></code></pre></div><p>Man erhält schnell Ergebnisse (wenn Ihnen ein Datensatz zu wenig ist, können Sie AI bitten, mehrere testbare Use Cases zu generieren): <img src="`+C+'" alt=""></p><p>Nach dem Klick erhalten wir das Ergebnis: <img src="'+B+'" alt=""></p><p>Was wir hier direkt erhalten, ist das Ergebnis – es gibt keinen &quot;simulierten Generierungsprozess&quot;. Wenn wir einen realistischen Generierungsprozess simulieren möchten, können wir direkt mit AI dialogieren: &quot;Bitte simuliere einen realistischen Generierungsprozess, bei dem die Ergebnisse erst nach einiger Zeit nach dem Klick angezeigt werden.&quot; <img src="'+W+'" alt=""></p><p>Nachdem die Generierungsfunktion durchlaufen ist, müssen wir auch sicherstellen, dass die Vorlagenbibliothek ordnungsgemäß funktioniert. Auf der Generierungskarte der Seite können wir sehen, dass die Vorlagenbibliothek-Speicherfunktion noch nicht implementiert ist. Jetzt müssen wir mit AI weitergehend kommunizieren: &quot;Bitte hilf mir sicherzustellen, dass die Anforderung [hier den Inhalt von Punkt 2 oben einfügen] erfüllt ist, ein Ergebnis angeklickt werden kann, um die entsprechende Vorlage zu speichern, und nach dem Öffnen die Generierungsparameter sichtbar sind.&quot;</p><p>Generierung ist oft nicht in einem Schritt erledigt – häufig sind Screenshots und Korrekturen nötig: <img src="'+D+'" alt=""></p><p>Schließlich erhalten wir das erwartete Ergebnis: <img src="'+T+'" alt=""></p><p>Neben der manuellen Überprüfung des Anforderungsprozesses können Sie AI auch bitten, direkt eine Anforderungsprüfung durchzuführen, zum Beispiel:</p><ul><li>&quot;Bitte vergleiche meine ursprünglichen Anforderungen und prüfe, ob die aktuelle Anwendung alle Kernfunktionen abdeckt.&quot;</li><li>&quot;Hilf mir, eine Funktionsliste zu erstellen, die markiert, was bereits fertig ist und was noch nicht implementiert ist oder unzureichend ist.&quot;</li></ul><p>AI gibt normalerweise eine Checkliste aus. Basierend auf den Ergebnissen können Sie überlegen, ob weitere Verbesserungen nötig sind. Nach wiederholten Überarbeitungen erhalten Sie einen relativ vollständigen Prototyp.</p><h2 id="_5-hausaufgabe-erstellen-sie-ihren-eigenen-douyin-e-commerce-workspace" tabindex="-1">5. Hausaufgabe: Erstellen Sie Ihren eigenen Douyin E-Commerce-Workspace <a class="header-anchor" href="#_5-hausaufgabe-erstellen-sie-ihren-eigenen-douyin-e-commerce-workspace" aria-label="Permalink to “5. Hausaufgabe: Erstellen Sie Ihren eigenen Douyin E-Commerce-Workspace”">​</a></h2>',15)),s(u,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:t(()=>[...n[2]||(n[2]=[e("div",{style:{"font-weight":"bold","font-size":"16px"}},"Herausforderung: E-Commerce-Material-Workspace nachbauen",-1)])]),default:t(()=>[n[3]||(n[3]=e("p",null," Referenzieren Sie die Prompts und Inhalte dieser Lektion und schließen Sie einen vollständigen Kreislauf ab: ",-1)),n[4]||(n[4]=e("ul",null,[e("li",null,[e("strong",null,"Vollständiger Praxis-Kreislauf"),e("ul",null,[e("li",null,"Geschäftsstrukturierung → Prompt-Generierung → Single-Page-Prototyp-Generierung → Multi-Page-Prototyp-Generierung")])]),e("li",null,[e("strong",null,"Ergebnisse teilen"),e("ul",null,[e("li",null,"Machen Sie Screenshots Ihres Programms und teilen Sie sie mit anderen")])]),e("li",null,[e("strong",null,"Denkaufgabe"),e("ul",null,[e("li",null,'Bereiten Sie sich auf die nächste Lektion "Anbindung von Large Language Models (LLM) und Text-to-Image-Fähigkeiten" vor und überlegen Sie im Voraus: Wie könnten Sie "AI-Copywriting / Bildgenerierung / Skriptgenerierung" etc. in Ihren Workspace einbetten?')])])],-1))]),_:1}),n[13]||(n[13]=e("h2",{id:"nachste-schritte",tabindex:"-1"},[i("Nächste Schritte "),e("a",{class:"header-anchor",href:"#nachste-schritte","aria-label":"Permalink to “Nächste Schritte”"},"​")],-1)),n[14]||(n[14]=e("p",null,"In der nächsten Lektion werden wir auf Basis dieses Content-Produktions-Workspaces konkrete AI-Fähigkeiten anbinden (Text-zu-Text, Bild-zu-Text, Text-zu-Bild), zum Beispiel:",-1)),n[15]||(n[15]=e("ul",null,[e("li",null,"Automatische Generierung von Copywriting-Entwürfen und mehreren Titel-Alternativen für eine Content-Aufgabe"),e("li",null,"Automatische Generierung von Bild-Entwürfen basierend auf der Aufgabenbeschreibung (Text-to-Image)"),e("li",null,"Automatische Kategorisierung und Zusammenfassung historischer Content-Aufgaben, um Sie bei der Planung des nächsten Events zu unterstützen")],-1)),s(h,{title:"Weiterlernen",description:"Empfehlung: in der Reihenfolge 'AI-Fähigkeiten anbinden → vollständiger Projekt-Kreislauf → Design-Engineering' fortsetzen.",items:V(p)},null,8,["items"])])}}});export{H as __pageData,L as default};
